import requests
from identity_models import UserProfile, normalize_claims

def fetch_profile_claims(access_token: str) -> UserProfile:
    headers = {
        'Authorization': f'Bearer {access_token}',
        'Content-Type': 'application/json'
    }
    response = requests.get("https://graph.microsoft.com/v1.0/me", headers=headers)
    response.raise_for_status()
    raw_claims = response.json()
    return normalize_claims(raw_claims)

import os
from google.cloud import language_v1

def moderate_claims_text(text_content: str) -> dict:
    client = language_v1.LanguageServiceClient()
    document = language_v1.Document(content=text_content, type_=language_v1.Document.Type.PLAIN_TEXT)

    # Classify text content for categories like "Sensitive" or "Violent"
    # This is a basic classification; for advanced moderation, consider custom models or other APIs.
    response = client.classify_text(request={'document': document})

    moderation_result = {
        "text_content": text_content,
        "categories": []
    }
    for category in response.categories:
        moderation_result["categories"].append({
            "name": category.name,
            "confidence": category.confidence
        })

    # You can also perform sentiment analysis or entity extraction if needed for moderation
    # sentiment = client.analyze_sentiment(request={'document': document}).document_sentiment
    # moderation_result["sentiment"] = {"score": sentiment.score, "magnitude": sentiment.magnitude}

    return moderation_result

import os
from google.cloud import firestore
from datetime import datetime

def store_login_audit_record(project_id: str, record: dict) -> dict:
    db = firestore.Client(project=project_id)
    collection_ref = db.collection("login_audit_records")

    # Add a timestamp if not already present
    if "timestamp" not in record:
        record["timestamp"] = datetime.utcnow()

    _, doc_ref = collection_ref.add(record)

    return {"status": "success", "document_id": doc_ref.id}

def get_login_audit_record(project_id: str, document_id: str) -> dict:
    db = firestore.Client(project=project_id)
    collection_ref = db.collection("login_audit_records")
    doc_ref = collection_ref.document(document_id)
    doc = doc_ref.get()
    if doc.exists:
        return {"status": "success", "data": doc.to_dict()}
    else:
        return {"status": "not_found", "message": f"Document with ID {document_id} not found."}
